<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useAuth } from '../stores/auth'
import { tradingApi } from '../api/trading'
import { profileApi } from '../api/profile'
import { operationsApi } from '../api/operations'
import OrdersView from './OrdersView.vue'
import WorkOrdersView from './WorkOrdersView.vue'

const auth=useAuth(),router=useRouter(),active=ref('dashboard'),account=ref<any>(null),orders=ref<any[]>([]),error=ref(''),loading=ref(true),profile=ref<any>({}),asset=ref<any>(null),holdings=ref<any[]>([]),history=ref<any[]>([]),riskOperation=ref<any>(null),myOperations=ref<any[]>([]),operationsTotal=ref(0),operationsType=ref(''),operationsStatus=ref(''),operationsLoading=ref(false),operationsMessage=ref(''),profileMessage=ref(''),profileError=ref(''),savingProfile=ref(false)
const items=[{key:'dashboard',label:'我的看板',icon:'▦'},{key:'profile',label:'个人信息',icon:'◉'},{key:'orders',label:'我的订单',icon:'▤'},{key:'workorders',label:'我的工单',icon:'☷'},{key:'operations',label:'业务办理',icon:'⇄'},{key:'assets',label:'资产与持仓',icon:'◇'},{key:'enterprise',label:'企业认证',icon:'▣'},{key:'risk',label:'风险测评',icon:'△'},{key:'advisor',label:'投顾服务',icon:'♙'},{key:'service',label:'智能客服',icon:'☏'}]
const currentTitle=computed(()=>items.find(item=>item.key===active.value)?.label||'我的看板')
const money=(value:any)=>Number(value||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})
const totalHoldingValue=computed(()=>holdings.value.reduce((sum,h)=>sum+Number(h.market_value||0),0))
const totalProfit=computed(()=>holdings.value.reduce((sum,h)=>sum+Number(h.profit_loss||0),0))
const chartPoints=computed(()=>{const rows=history.value;if(!rows.length)return '';const w=560,h=180,p=14;const values=rows.map(x=>Number(x.total_asset||0));const min=Math.min(...values),max=Math.max(...values),span=max-min||1;return rows.map((x,i)=>`${p+i*((w-p*2)/Math.max(1,rows.length-1))},${h-p-((Number(x.total_asset)-min)/span)*(h-p*2)}`).join(' ')})
const chartMin=computed(()=>history.value.length?Math.min(...history.value.map(x=>Number(x.total_asset||0))):0)
const chartMax=computed(()=>history.value.length?Math.max(...history.value.map(x=>Number(x.total_asset||0))):0)
const chartTicks=computed(()=>{const max=chartMax.value,min=chartMin.value;const span=max-min||1;return [0,0.25,0.5,0.75,1].map(ratio=>({value:max-span*ratio,y:14+ratio*152}))})
const chartDate=(row:any)=>{const value=row?.snapshot_time;if(!value)return '—';const date=new Date(value);return Number.isNaN(date.getTime())?'—':date.toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'})}
const chartLabels=computed(()=>{const rows=history.value;if(!rows.length)return [];const indexes=Array.from(new Set([0,Math.floor((rows.length-1)/2),rows.length-1]));return indexes.map(index=>({label:chartDate(rows[index]),x:14+index*((560-28)/Math.max(1,rows.length-1))}))})
const cashShare=computed(()=>{const total=Number(asset.value?.total_asset||0);return total?Math.round(Number(asset.value?.cash_balance||0)/total*100):0})
const allocationStyle=computed(()=>`conic-gradient(#3a6cf4 0 ${cashShare.value}%, #42b8ca ${cashShare.value}% 100%)`)
const maxProfit=computed(()=>Math.max(1,...holdings.value.map(h=>Math.abs(Number(h.profit_loss||0)))))
const riskText:Record<string,string>={normal:'正常',monitoring:'风险关注',restricted:'交易限制'}
const riskHint=computed(()=>{const risk=riskOperation.value;if(!risk||risk.status==='normal')return '当前账户未发现未关闭的风险预警，可正常使用交易服务。';if(risk.status==='restricted')return `当前账户已限制交易${risk.restriction_reason?`：${risk.restriction_reason}`:''}。如有疑问，请联系客户经理。`;return `当前账户处于风险关注状态${risk.latest_rule_code?`（${risk.latest_rule_code}）`:''}，交易服务可能受到额外审核。`})
async function refresh(){const [accountRes,orderRes,summaryRes,historyRes]=await Promise.all([tradingApi.account(),tradingApi.orders(),profileApi.summary(),profileApi.assetHistory(60)]);account.value=accountRes.data.data;orders.value=orderRes.data.data;const summary=summaryRes.data.data;profile.value=summary.profile||{};asset.value=summary.latest_asset||null;holdings.value=summary.holdings||[];history.value=historyRes.data.data.items||[];riskOperation.value=summary.risk_operation||null}
const operationStatusText:Record<string,string>={pending_review:'待审核',settled:'已结算',rejected:'已拒绝'}
const operationActionText:Record<string,string>={submit:'已提交',settle:'审核通过',reject:'审核拒绝'}
const operationForm=ref({product_id:'',quantity:'',amount:'',to_account:'',transfer_amount:'',confirmed:false})
const operationSubmitting=ref('')
function idempotencyKey(prefix:string){return `${prefix}:${crypto.randomUUID()}`}
async function submitRedeem(){
  operationsMessage.value=''
  const quantity=Number(operationForm.value.quantity), amount=Number(operationForm.value.amount)
  if(!operationForm.value.product_id||!Number.isFinite(quantity)||quantity<=0||!Number.isFinite(amount)||amount<=0){operationsMessage.value='请填写产品 ID、赎回数量和金额。';return}
  operationSubmitting.value='redeem'
  try{await operationsApi.redeem({product_id:operationForm.value.product_id.trim(),quantity,amount,idempotency_key:idempotencyKey('customer-redeem')});operationsMessage.value='赎回申请已提交，等待工作人员审核。';operationForm.value.product_id='';operationForm.value.quantity='';operationForm.value.amount='';await Promise.all([loadMyOperations(),refresh()])}catch(e:any){operationsMessage.value=e.message||'赎回申请提交失败'}finally{operationSubmitting.value=''}
}
async function submitTransfer(){
  operationsMessage.value=''
  const amount=Number(operationForm.value.transfer_amount)
  if(!operationForm.value.to_account.trim()||!Number.isFinite(amount)||amount<=0){operationsMessage.value='请填写收款账户和转账金额。';return}
  if(!operationForm.value.confirmed){operationsMessage.value='请勾选确认信息无误后再提交转账申请。';return}
  operationSubmitting.value='transfer'
  try{await operationsApi.transfer({to_account:operationForm.value.to_account.trim(),amount,confirmed:true,idempotency_key:idempotencyKey('customer-transfer')});operationsMessage.value='转账申请已提交，等待工作人员审核。';operationForm.value.to_account='';operationForm.value.transfer_amount='';operationForm.value.confirmed=false;await Promise.all([loadMyOperations(),refresh()])}catch(e:any){operationsMessage.value=e.message||'转账申请提交失败'}finally{operationSubmitting.value=''}
}
async function loadMyOperations(){operationsLoading.value=true;operationsMessage.value='';try{const r=(await operationsApi.mine({operation_type:(operationsType.value||undefined) as any,status:operationsStatus.value||undefined,limit:50})).data.data;myOperations.value=r.items;operationsTotal.value=r.total}catch(e:any){operationsMessage.value=e.response?.data?.detail?.message||e.message||'业务操作加载失败'}finally{operationsLoading.value=false}}
function operationFilterChanged(){loadMyOperations()}
async function saveProfile(){savingProfile.value=true;profileMessage.value='';profileError.value='';try{profile.value=(await profileApi.updateProfile({age:profile.value.age,occupation:profile.value.occupation||'',region:profile.value.region||'',investment_goal:profile.value.investment_goal||'',investment_horizon_years:profile.value.investment_horizon_years||5,liquidity_preference:profile.value.liquidity_preference||'medium'})).data.data;profileMessage.value='个人信息已更新'}catch(e:any){profileError.value=e.response?.data?.detail||e.message}finally{savingProfile.value=false}}
async function logout(){await auth.logout();await router.push('/login')}
onMounted(async()=>{try{await Promise.all([refresh(),loadMyOperations()])}catch(e:any){error.value=e.response?.data?.detail||e.message}finally{loading.value=false}})
</script>
<template>
<div class="portal-shell customer-portal"><aside class="portal-sidebar"><div class="portal-brand"><div class="portal-logo">W</div><div><strong>财富管理平台</strong><small>客户服务端</small></div></div><div class="portal-user"><div class="portal-avatar">{{(auth.me.value?.display_name||'客').slice(0,1)}}</div><div><strong>{{auth.me.value?.display_name}}</strong><small>客户</small></div></div><nav class="portal-nav"><button class="portal-return" @click="router.push('/')"><span>⌂</span> 返回前台</button><div class="portal-divider"></div><button v-for="item in items" :key="item.key" :class="{active:active===item.key}" @click="active=item.key"><span class="portal-icon">{{item.icon}}</span>{{item.label}}</button></nav><button class="portal-logout" @click="logout"><span>↪</span> 退出登录</button></aside><main class="portal-main"><header class="portal-content-header"><div><p>当前位置 / {{currentTitle}}</p><h1>{{currentTitle}}</h1></div><div class="portal-header-badge customer">客户中心</div></header><section class="portal-content-body"><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="empty">正在读取客户数据…</div><template v-else><div v-if="active==='dashboard'" class="portal-dashboard"><div class="portal-stat-grid"><article><span>总资产</span><strong>¥{{money(asset?.total_asset)}}</strong></article><article><span>可用余额</span><strong>¥{{money(account?.available_balance)}}</strong></article><article><span>持仓市值</span><strong>¥{{money(totalHoldingValue)}}</strong></article></div><div class="portal-panel dashboard-asset-note"><strong>资产数据说明</strong><span>总资产 = 可用余额 + 冻结余额 + 当前持仓市场价值；每次进入客户中心会按最新持仓估值刷新。</span></div><div class="portal-panel customer-risk-banner" :class="'risk-'+(riskOperation?.status||'normal')"><div><span>账户风控状态</span><strong>{{riskText[riskOperation?.status]||'正常'}}</strong></div><p>{{riskHint}}</p><small v-if="riskOperation?.latest_rule_code">当前规则：{{riskOperation.latest_rule_code}} · 预警等级：{{riskOperation.latest_alert_level||'—'}}</small></div></div><div v-else-if="active==='service'" class="portal-panel"><h2>智能客服</h2><p>咨询公司信息、业务、FAQ、流程、政策和资料规则。</p><RouterLink class="button" to="/customer-center/service">进入智能客服</RouterLink></div><div v-else-if="active==='advisor'" class="portal-panel"><h2>投顾服务</h2><p>查看当前投顾授权、操作草稿并完成客户确认。</p><RouterLink class="button" to="/customer-center/advisor">进入投顾服务</RouterLink></div><div v-else-if="active==='risk'" class="portal-panel"><h2>风险测评</h2><p>完成风险测评，系统将根据结果判断产品适配范围。</p><RouterLink class="button" to="/customer-center/risk-assessment">进入风险测评</RouterLink></div><div v-else-if="active==='enterprise'" class="portal-panel"><h2>企业客户认证</h2><p>提交企业资料，审核通过后可转为企业客户。</p><RouterLink class="button" to="/customer-center/enterprise-verification">进入认证申请</RouterLink></div><div v-else-if="active==='profile'" class="portal-panel"><h2>个人信息</h2><p v-if="profileMessage" class="success">{{profileMessage}}</p><p v-if="profileError" class="error">{{profileError}}</p><form class="product-editor-grid" @submit.prevent="saveProfile"><label>用户名<input :value="auth.me.value?.username" disabled></label><label>显示名称<input :value="auth.me.value?.display_name" disabled></label><label>年龄<input v-model.number="profile.age" type="number" min="0" max="150"></label><label>职业<input v-model="profile.occupation"></label><label>地区<input v-model="profile.region"></label><label class="full">投资目标<select v-model="profile.investment_goal"><option value="capital_preservation">资产保值</option><option value="income">稳定收益</option><option value="balanced">均衡配置</option><option value="growth">资产增长</option><option value="aggressive">高风险增值</option></select></label><label>投资期限（年）<input v-model.number="profile.investment_horizon_years" type="number" min="0" max="100"></label><label>流动性偏好<select v-model="profile.liquidity_preference"><option value="high">高</option><option value="medium">中</option><option value="low">低</option></select></label><label class="full"><button class="button" :disabled="savingProfile">{{savingProfile?'保存中':'保存个人信息'}}</button></label></form></div><OrdersView v-else-if="active==='orders'"/><WorkOrdersView v-else-if="active==='workorders'" :customer-mode="true"/><div v-else-if="active==='operations'" class="portal-panel customer-operations-panel"><div class="customer-operations-head"><div><span>MY OPERATIONS</span><h2>转账与赎回办理</h2><p>提交申请后将进入审核队列；风险限制、余额、持仓和适当性校验仍由后端执行。</p></div><strong>{{operationsTotal}}</strong></div><div class="customer-operation-forms"><form class="customer-operation-form" @submit.prevent="submitRedeem"><div><span>REDEEM</span><h3>发起赎回</h3><p>填写持仓对应的产品 ID、赎回数量和申请金额。</p></div><label>产品 ID<input v-model="operationForm.product_id" placeholder="输入持仓产品 ID"></label><label>赎回数量<input v-model="operationForm.quantity" type="number" min="0.01" step="0.01"></label><label>赎回金额<input v-model="operationForm.amount" type="number" min="0.01" step="0.01"></label><button class="button" :disabled="operationSubmitting==='redeem'">{{operationSubmitting==='redeem'?'提交中…':'提交赎回申请'}}</button></form><form class="customer-operation-form" @submit.prevent="submitTransfer"><div><span>TRANSFER</span><h3>发起转账</h3><p>转账提交后需要工作人员审核；请确认收款账户和金额。</p></div><label>收款账户<input v-model="operationForm.to_account" placeholder="输入目标账户号"></label><label>转账金额<input v-model="operationForm.transfer_amount" type="number" min="0.01" step="0.01"></label><label class="customer-operation-confirm"><input v-model="operationForm.confirmed" type="checkbox"> 我已确认收款账户和金额无误</label><button class="button" :disabled="operationSubmitting==='transfer'">{{operationSubmitting==='transfer'?'提交中…':'提交转账申请'}}</button></form></div><div class="customer-operation-filters"><select v-model="operationsType" @change="operationFilterChanged"><option value="">全部业务</option><option value="transfer">我的转账</option><option value="redeem">我的赎回</option></select><select v-model="operationsStatus" @change="operationFilterChanged"><option value="">全部状态</option><option value="pending_review">待审核</option><option value="settled">已结算</option><option value="rejected">已拒绝</option></select><button class="button" @click="loadMyOperations">刷新</button></div><p v-if="operationsMessage" class="error">{{operationsMessage}}</p><div v-if="operationsLoading" class="chart-empty">正在读取业务办理记录…</div><div v-else-if="!myOperations.length" class="chart-empty">暂无匹配的转账或赎回申请。</div><div v-else class="customer-operation-list"><article v-for="item in myOperations" :key="item.operation_id" class="customer-operation-card" :class="item.operation"><div class="customer-operation-top"><div><span class="operation-kind">{{item.operation==='transfer'?'转账':'赎回'}}</span><strong>{{item.operation==='transfer'?'转账申请':'赎回申请'}}</strong><small>{{new Date(item.created_at).toLocaleString('zh-CN',{hour12:false})}}</small></div><span class="status-chip" :class="item.status">{{operationStatusText[item.status]||item.status}}</span></div><dl><template v-if="item.operation==='transfer'"><dt>收款账户</dt><dd>{{item.to_account||'—'}}</dd></template><template v-else><dt>产品 / 数量</dt><dd>{{item.product_name||item.product_id}} · {{item.quantity}}</dd></template><dt>金额</dt><dd>¥{{money(item.amount)}}</dd><dt>申请方式</dt><dd>{{item.operator_user_id?'工作人员代办':'客户本人发起'}} · {{item.confirmation_mode||'—'}}</dd><dt>最新进度</dt><dd>{{operationActionText[item.latest_action]||item.latest_action||'处理中'}}<span v-if="item.latest_note"> · {{item.latest_note}}</span></dd></dl></article></div></div><div v-else-if="active==='assets'" class="asset-workspace"><div class="asset-hero"><div><span>总资产</span><strong>¥{{money(asset?.total_asset)}}</strong><small>快照时间 {{asset?.snapshot_time?new Date(asset.snapshot_time).toLocaleString('zh-CN',{hour12:false}):'实时派生'}}</small></div><div class="asset-hero-metrics"><p><span>现金资产</span><strong>¥{{money(asset?.cash_balance)}}</strong></p><p><span>净资产</span><strong>¥{{money(asset?.net_asset)}}</strong></p><p><span>累计浮盈</span><strong class="positive-value">+¥{{money(totalProfit)}}</strong></p></div></div><div class="asset-chart-grid"><section class="asset-chart-card trend-card"><div class="chart-card-head"><div><span>ASSET HISTORY</span><h3>资产趋势</h3></div><small>{{history.length}} 个快照</small></div><div v-if="history.length>1" class="trend-chart"><svg viewBox="0 0 560 180" role="img" aria-label="总资产趋势"><defs><linearGradient id="assetArea" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#3a6cf4" stop-opacity=".28"/><stop offset="1" stop-color="#3a6cf4" stop-opacity="0"/></linearGradient></defs><g class="trend-grid" v-for="tick in chartTicks" :key="tick.y"><line x1="14" :y1="tick.y" x2="546" :y2="tick.y"/><text x="8" :y="tick.y+3" text-anchor="end">¥{{money(tick.value)}}</text></g><line class="trend-x-axis" x1="14" y1="166" x2="546" y2="166"/><polyline :points="chartPoints+' 546,166 14,166'" fill="url(#assetArea)" stroke="none"/><polyline :points="chartPoints" fill="none" stroke="#3a6cf4" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><g class="trend-x-labels" v-for="item in chartLabels" :key="item.x"><line :x1="item.x" y1="166" :x2="item.x" y2="170"/><text :x="item.x" y="179" text-anchor="middle">{{item.label}}</text></g></svg></div><div v-else class="chart-empty">完成更多交易、赎回或转账后，这里会形成资产趋势。</div></section><section class="asset-chart-card allocation-card"><div class="chart-card-head"><div><span>ALLOCATION</span><h3>资产配置</h3></div></div><div class="allocation-wrap"><div class="allocation-donut" :style="{background:allocationStyle}"><div><strong>{{cashShare}}%</strong><span>现金</span></div></div><div class="allocation-legend"><p><i class="cash-dot"></i><span>现金资产</span><strong>¥{{money(asset?.cash_balance)}}</strong></p><p><i class="holding-dot"></i><span>持仓市值</span><strong>¥{{money(totalHoldingValue)}}</strong></p></div></div></section><section class="asset-chart-card profit-card"><div class="chart-card-head"><div><span>HOLDING P&L</span><h3>持仓收益</h3></div><small class="positive-value">+¥{{money(totalProfit)}}</small></div><div v-if="holdings.length" class="profit-bars"><div v-for="holding in holdings" :key="holding.id" class="profit-row"><div><strong>{{holding.product_name||'未知产品'}}</strong><small>日收益 +{{(Number(holding.daily_yield_rate||0)*100).toFixed(3)}}%</small></div><div class="profit-track"><span :style="{width:Math.max(5,Math.abs(Number(holding.profit_loss||0))/maxProfit*100)+'%'}"></span></div><b>+¥{{money(holding.profit_loss)}}</b></div></div><div v-else class="chart-empty">暂无持仓收益数据。</div></section></div><div class="asset-table-panel"><div class="asset-panel-head"><div><span>POSITION BOOK</span><h2>当前持仓</h2></div><small>共 {{holdings.length}} 项</small></div><div class="module-table-wrap"><table class="admin-table asset-table"><thead><tr><th>产品名称</th><th>日收益率</th><th>持有数量</th><th>成本金额</th><th>市场价值</th><th>累计收益率</th><th>浮动盈亏</th><th>持有天数</th><th>状态</th></tr></thead><tbody><tr v-for="holding in holdings" :key="holding.id"><td><strong>{{holding.product_name||'未知产品'}}</strong><small class="holding-product-id">{{holding.product_id}}</small></td><td class="yield-rate">+{{(Number(holding.daily_yield_rate||0)*100).toFixed(3)}}%</td><td>{{Number(holding.quantity||0).toLocaleString()}}</td><td>¥{{money(holding.cost_amount)}}</td><td>¥{{money(holding.market_value)}}</td><td class="positive-value">+{{(Number(holding.cumulative_return_rate||0)*100).toFixed(2)}}%</td><td :class="Number(holding.profit_loss)>=0?'positive-value':'negative-value'">{{Number(holding.profit_loss)>=0?'+':''}}¥{{money(holding.profit_loss)}}</td><td>{{holding.holding_days||0}} 天</td><td><span class="status-chip settled">{{holding.status==='active'?'持有中':holding.status}}</span></td></tr><tr v-if="!holdings.length"><td colspan="9" class="table-empty">暂无持仓</td></tr></tbody></table></div></div></div><div v-else class="portal-panel"><h2>{{currentTitle}}</h2><p>该功能正在建设中。</p></div></template></section></main></div>
</template>
